const view=document.querySelector('#view');
const modal=document.querySelector('#modal');
const modalContent=document.querySelector('#modalContent');
const modalClose=document.querySelector('#modalClose');
const photoInput=document.querySelector('#photoInput');
const topTitle=document.querySelector('#topTitle');

const savedPhotos=JSON.parse(localStorage.getItem('ipa_beta06_photos')||'[]');
const savedProfile=localStorage.getItem('ipa_beta06_profile')||'client';
const state={route:'today',mode:'during',profile:savedProfile,leadStage:'new',tripDay:1,steps:12480,shareLocation:false,live:false,liveSeconds:0,liveTimer:null,liveViewers:23,reactions:14,photos:savedPhotos,messages:[
 {type:'guide',name:'Renato · Guia',text:'Bom dia, pessoal! Nosso encontro será às 09h15 na entrada principal.',time:'08:45'},
 {type:'other',name:'Juliana',text:'Perfeito! Já estamos a caminho ☀️',time:'08:47'},
 {type:'other',name:'Carlos',text:'Alguém sabe se vai chover à tarde?',time:'08:50'}
]};
const titles={today:'Hoje',trip:'Minha Viagem',explore:'Explorar',community:'Grupo da viagem',memories:'Memórias',diary:'Diário da Viagem',prospect:'Planejar viagem'};

document.addEventListener('click', event => {
 const modeButton = event.target.closest('[data-mode]');
 if(!modeButton) return;
 event.preventDefault();
 event.stopPropagation();
 state.mode = modeButton.dataset.mode;
 state.route = 'today';
 render();
});


setTimeout(()=>document.querySelector('#splash').classList.add('hide'),1800);
if('serviceWorker' in navigator) navigator.serviceWorker.register('./service-worker.js');
function money(n){return new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n)}
function timeFmt(s){const m=String(Math.floor(s/60)).padStart(2,'0'),sec=String(s%60).padStart(2,'0');return `${m}:${sec}`}
function setProfile(profile){state.profile=profile;localStorage.setItem('ipa_beta06_profile',profile);state.route=profile==='prospect'?'prospect':'today';render()}
function render(){
 topTitle.textContent=titles[state.route]||'Indo por Aí';
 view.innerHTML=routes[state.route]();
 document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.route===state.route));
 document.body.classList.toggle('hidden-nav',state.profile==='prospect');
 bind(); window.scrollTo({top:0,behavior:'smooth'});
}
function bind(){
 document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{state.route=b.dataset.go;render()});
 document.querySelectorAll('[data-modal]').forEach(b=>b.onclick=()=>showModal(b.dataset.modal));
 document.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>window.open('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(b.dataset.map),'_blank'));
 document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>setProfile(b.dataset.profile));
 document.querySelectorAll('#liveBtn').forEach(b=>b.onclick=toggleLive);
 document.querySelectorAll('#addPhoto').forEach(b=>b.onclick=()=>photoInput.click());

 document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{state.tripDay=Number(b.dataset.day);render()});
 const realLiveBtn=document.querySelector('#realLiveBtn');
 if(realLiveBtn)realLiveBtn.onclick=()=>window.location.href='live-real.html';
 const shareLocationBtn=document.querySelector('#shareLocationBtn');
 if(shareLocationBtn)shareLocationBtn.onclick=()=>{
  if(!navigator.geolocation){toast('Localização não suportada neste aparelho');return;}
  toast('Buscando sua localização...');
  navigator.geolocation.getCurrentPosition(()=>toast('Localização compartilhada por 1 hora'),()=>toast('Autorize a localização no Safari'),{enableHighAccuracy:true,timeout:10000});
 };
 document.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>toast(`Centralizando em ${b.dataset.person}`));
 document.querySelectorAll('[data-open-movie]').forEach(btn=>btn.onclick=()=>openTravelMovie());
 document.querySelectorAll('[data-open-album]').forEach(btn=>btn.onclick=()=>{state.route='memories';render();});
 document.querySelectorAll('[data-memory-day]').forEach(btn=>btn.onclick=()=>showMemoryDay(btn.dataset.memoryDay));
 document.querySelectorAll('[data-concierge]').forEach(btn=>btn.onclick=()=>openConcierge());
 document.querySelectorAll('[data-journey-step]').forEach(btn=>btn.onclick=()=>showJourneyStep(btn.dataset.journeyStep));
 document.querySelectorAll('[data-diary]').forEach(btn=>btn.onclick=()=>showTravelDiary());
 document.querySelectorAll('[data-admin-preview]').forEach(btn=>btn.onclick=()=>showAdminPreview());
 document.querySelectorAll('[data-boarding-pass]').forEach(btn=>btn.onclick=()=>showBoardingPass());
 document.querySelectorAll('[data-open-diary-page]').forEach(btn=>btn.onclick=()=>{state.route='diary';render();});
 document.querySelectorAll('[data-concierge-choice]').forEach(btn=>btn.onclick=()=>showConciergeResult(btn.dataset.conciergeChoice));
 const instagramBtn=document.querySelector('#instagramBtn');
 if(instagramBtn)instagramBtn.onclick=()=>window.open('https://www.instagram.com/indo.por.ai.com.a.gente/','_blank');
 document.querySelectorAll('[data-discovery]').forEach(card=>card.onclick=()=>{
   const data=JSON.parse(card.dataset.discovery);
   showModal(`<h2>${data.icon} ${data.name}</h2><p><b>${data.rating}</b> · ${data.reviews} avaliações</p><p>${data.description}</p><div class="discovery-detail-grid"><div><small>Distância</small><strong>${data.distance}</strong></div><div><small>Tempo extra</small><strong>${data.detour}</strong></div><div><small>Preço</small><strong>${data.price}</strong></div></div><button class="btn btn-primary btn-block" onclick="toast('Parada adicionada ao roteiro');modal.close()">Adicionar ao roteiro</button><button class="btn btn-light btn-block" data-map="${data.name} Portugal">Abrir no mapa</button>`);
 });
 const preTripSurprise=document.querySelector('#preTripSurprise');
 if(preTripSurprise)preTripSurprise.onclick=()=>showModal(`<h2>✨ Descoberta para sua viagem</h2><div class="card"><span class="chip orange">Recomendação Indo por Aí</span><h3>Quinta da Pacheca</h3><p>Uma experiência no Vale do Douro com visita, degustação e almoço. Disponível para o dia 4 da sua viagem.</p><div class="proposal-total"><strong>R$ 690</strong><small>por pessoa</small></div><br><button class="btn btn-primary btn-block" onclick="toast('Solicitação enviada ao concierge');modal.close()">Quero reservar</button></div>`);

 const send=document.querySelector('#sendMessage');if(send)send.onclick=sendMessage;
 const surprise=document.querySelector('#surpriseBtn');if(surprise)surprise.onclick=()=>showModal(`<h2>✨ Surpresa perto de você</h2><div class="card"><span class="chip orange">A 180 metros</span><h3>Gelateria Portuense</h3><p>Avaliação 4,9 · combina com seu perfil e com o orçamento do dia.</p><br><button class="btn btn-primary btn-block" data-map="Gelateria Portuense Porto">Ir agora</button></div>`);
 const lead=document.querySelector('#leadForm');if(lead)lead.onsubmit=submitLead;
 const proposal=document.querySelector('#approveProposal');if(proposal)proposal.onclick=()=>{state.leadStage='approved';toast('Planejamento aprovado!');render()};
 document.querySelectorAll('[data-reaction]').forEach(b=>b.onclick=()=>addReaction(b.dataset.reaction));
 const shareLocation=document.querySelector('#shareLocation');if(shareLocation)shareLocation.onclick=()=>toast('Localização compartilhada com o grupo');
 const livePhoto=document.querySelector('#livePhoto');if(livePhoto)livePhoto.onclick=()=>photoInput.click();
 const mic=document.querySelector('#liveMic');if(mic)mic.onclick=()=>{mic.classList.toggle('active');toast(mic.classList.contains('active')?'Microfone ativado':'Microfone silenciado')};
}

document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>{state.route=b.dataset.route;render()});
modalClose.onclick=()=>modal.close();
photoInput.onchange=handlePhotos;
document.querySelector('#profileBtn').onclick=openAdmin;
document.querySelector('#menuBtn').onclick=()=>showModal(`<img src="data:image/png;base64," style="width:210px;display:block;margin:auto"><h2>Escolha o cenário de teste</h2><div class="segmented"><button data-profile="prospect">Ainda não sou cliente</button><button data-profile="client">Já sou cliente</button></div><p>Use os dois perfis para testar a jornada comercial e a experiência durante a viagem.</p>`);

const routes={
 prospect:()=>prospectView(),
 today:()=>state.mode==='before'?beforeView():state.mode==='after'?afterView():duringView(),
 trip:()=>tripView(),
 explore:()=>exploreView(),
 community:()=>state.live?liveView():communityView(),
 memories:()=>memoriesView()
};

function prospectView(){
 if(state.leadStage==='sent')return `<section class="card proposal-card"><div class="state-banner"><div><span class="eyebrow">Solicitação recebida</span><h1>Agora é com a gente.</h1><p>Estamos preparando uma proposta personalizada para sua viagem.</p></div><img src="data:image/png;base64," alt="Indo por Aí"></div></section><section class="section"><div class="timeline"><div class="timeline-item"><span class="status done">✓</span><div><b>Pedido recebido</b><small>Hoje · 14:20</small></div></div><div class="timeline-item"><span class="status doing">2</span><div><b>Curadoria em andamento</b><small>Voos, hotel e experiências</small></div></div><div class="timeline-item"><span class="status pending">3</span><div><b>Proposta para aprovação</b><small>Previsão: hoje às 18h</small></div></div></div></section><section class="section"><div class="card"><span class="chip orange">Simulação</span><h3>Sua proposta ficou pronta</h3><p>Portugal · 8 dias · 2 pessoas · experiência completa.</p><br><button class="btn btn-primary btn-block" id="approveProposal">Ver e aprovar proposta</button></div></section><section class="section"><button class="btn btn-outline btn-block" data-profile="client">Simular cliente contratado</button></section>`;
 if(state.leadStage==='approved')return `<section class="hero prospect-hero"><img class="hero-logo" src="data:image/png;base64," alt="Indo por Aí"><span class="eyebrow">Planejamento aprovado</span><h1>Sua viagem começou antes do embarque.</h1><p>Nossa equipe já pode iniciar as reservas e informar cada passo pelo aplicativo.</p><div class="hero-actions"><button class="btn btn-primary" data-profile="client">Entrar na minha viagem</button></div></section>`;
 return `<section class="hero prospect-hero"><img class="hero-logo" src="data:image/png;base64," alt="Indo por Aí"><span class="eyebrow">Ainda não é cliente?</span><h1>Você sonha. A gente organiza.</h1><p>Planejamento, compras, roteiro, concierge e acompanhamento em um só lugar.</p><div class="hero-actions"><button class="btn btn-primary" data-go="prospect-form">Quero planejar minha viagem</button><button class="btn btn-light" data-profile="client">Já sou cliente</button></div></section>
 <section class="section"><div class="section-head"><h2>Como cuidamos da sua viagem</h2></div><div class="service-list"><div class="card service-card"><div class="service-icon">🧭</div><div><b>Planejamento personalizado</b><p>Roteiro feito para seu perfil e orçamento.</p></div><span>›</span></div><div class="card service-card"><div class="service-icon">🛒</div><div><b>Compramos tudo para você</b><p>Passagens, hotel, transfer, seguro e experiências.</p></div><span>›</span></div><div class="card service-card"><div class="service-icon">📲</div><div><b>Acompanhamento passo a passo</b><p>Você acompanha cada cotação, aprovação e reserva.</p></div><span>›</span></div><div class="card service-card"><div class="service-icon">🎧</div><div><b>Concierge durante a viagem</b><p>Suporte humano, grupo, mapa e modo ao vivo.</p></div><span>›</span></div></div></section>
 <section class="section"><div class="card"><span class="eyebrow">Como funciona</span><div class="journey-step"><span class="step-dot">1</span><div><b>Conte seu sonho</b><p>Destino, datas, orçamento e preferências.</p></div></div><div class="journey-step"><span class="step-dot">2</span><div><b>Receba sua proposta</b><p>Opções com preços e próximos passos.</p></div></div><div class="journey-step"><span class="step-dot">3</span><div><b>Aprove e acompanhe</b><p>Nossa equipe compra e informa tudo pelo app.</p></div></div></div></section>
 <section class="section" id="prospect-form"><div class="section-head"><h2>Vamos começar?</h2></div><form id="leadForm" class="card lead-form"><input required name="name" placeholder="Nome completo"><input required type="email" name="email" placeholder="E-mail"><input name="phone" placeholder="WhatsApp"><input required name="destination" placeholder="Para onde você quer viajar?"><input name="date" placeholder="Quando pretende viajar?"><select name="people"><option>Quantas pessoas?</option><option>1 pessoa</option><option>2 pessoas</option><option>3 a 5 pessoas</option><option>6 ou mais</option></select><textarea name="dream" placeholder="Conte um pouco sobre a viagem dos seus sonhos"></textarea><button class="btn btn-primary btn-block" type="submit">Enviar para o Indo por Aí</button></form></section>`;
}
